begin;
create table if not exists public.world_english_questions(
 id text primary key,level int not null check(level between 1 and 10),prompt text not null,choices jsonb not null check(jsonb_array_length(choices)=3),correct_index int not null check(correct_index between 0 and 2),explanation text not null,tag text not null,context_id text not null,active boolean not null default true
);
create index if not exists world_english_questions_level on public.world_english_questions(level) where active;
create table if not exists public.world_english_runs(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),request_id uuid not null,score int not null default 0,status text not null default 'question' check(status in('question','review','lost','quit','completed')),reason text,created_at timestamptz not null default clock_timestamp(),ended_at timestamptz,unique(user_id,request_id)
);
create unique index if not exists world_english_one_active on public.world_english_runs(user_id) where status in('question','review');
create index if not exists world_english_runs_user on public.world_english_runs(user_id,created_at desc);
create table if not exists public.world_english_turns(
 id uuid primary key default gen_random_uuid(),run_id uuid not null references public.world_english_runs(id),seq int not null,question_id text not null,tag text not null,context_id text not null,prompt text not null,choices jsonb not null,correct_index int not null,explanation text not null,issued_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default clock_timestamp()+interval '30 seconds',answered_at timestamptz,chosen int,correct boolean,points int not null default 0,unique(run_id,seq),unique(run_id,question_id)
);
create table if not exists public.world_english_best(user_id uuid primary key references public.profiles(id),score int not null,reached_at timestamptz not null default clock_timestamp());
create table if not exists public.world_english_daily(user_id uuid not null references public.profiles(id),day date not null,best_score int not null default 0,points int not null default 0,primary key(user_id,day));
create table if not exists public.world_english_requests(user_id uuid not null references public.profiles(id),request_id uuid not null,payload jsonb not null,result jsonb not null,primary key(user_id,request_id));
-- ENGLISH_BANK_BEGIN
