insert into public.world_english_questions(id,level,prompt,choices,correct_index,explanation,tag,context_id) select id,level,prompt,choices,correct_index,explanation,tag,context_id from jsonb_to_recordset($bank$[{"id":"EN09-0001","level":9,"prompt":"The new barriers should ___ the effects of flooding.\n(의미 단서: 완화하다)","choices":["aggravate","mitigate","maintain"],"correct_index":1,"explanation":"mitigate는 ‘완화하다’라는 뜻으로 문장의 의미 단서에 맞습니다. aggravate는 ‘악화시키다’, maintain는 ‘유지하다’입니다.","tag":"vocab-mitigate","context_id":"vocab-001"},{"id":"EN09-0002","level":9,"prompt":"A backup generator can ___ the impact of a power outage.\n(의미 단서: 완화하다)","choices":["aggravate","mitigate","maintain"],"correct_index":1,"explanation":"mitigate는 ‘완화하다’라는 뜻으로 문장의 의미 단서에 맞습니다. aggravate는 ‘악화시키다’, maintain는 ‘유지하다’입니다.","tag":"vocab-mitigate","context_id":"vocab-001"},{"id":"EN09-0003","level":9,"prompt":"The mediator proposed a compromise to ___ the conflict.\n(의미 단서: 완화하다)","choices":["mitigate","aggravate","maintain"],"correct_index":0,"explanation":"mitigate는 ‘완화하다’라는 뜻으로 문장의 의미 단서에 맞습니다. aggravate는 ‘악화시키다’, maintain는 ‘유지하다’입니다.","tag":"vocab-mitigate","context_id":"vocab-001"},{"id":"EN09-0004","level":9,"prompt":"Flexible deadlines may ___ the pressure on new staff.\n(의미 단서: 완화하다)","choices":["mitigate","maintain","aggravate"],"correct_index":0,"explanation":"mitigate는 ‘완화하다’라는 뜻으로 문장의 의미 단서에 맞습니다. aggravate는 ‘악화시키다’, maintain는 ‘유지하다’입니다.","tag":"vocab-mitigate","context_id":"vocab-001"},{"id":"EN09-0005","level":9,"prompt":"Extra ventilation will ___ the discomfort caused by heat.\n(의미 단서: 완화하다)","choices":["mitigate","maintain","aggravate"],"correct_index":0,"explanation":"mitigate는 ‘완화하다’라는 뜻으로 문장의 의미 단서에 맞습니다. aggravate는 ‘악화시키다’, maintain는 ‘유지하다’입니다.","tag":"vocab-mitigate","context_id":"vocab-001"},{"id":"EN09-0006","level":9,"prompt":"The council will ___ funds to the library and the park.\n(의미 단서: 배분하다)","choices":["withdraw","allocate","waste"],"correct_index":1,"explanation":"alloc