create or replace function public.world_english_issue(p_run uuid) returns void language plpgsql security definer set search_path=public as $$
declare r world_english_runs;q world_english_questions;order_ids int[];shuffled jsonb;answer_pos int;
begin
 select * into r from world_english_runs where id=p_run for update;
 select q0.* into q from world_english_questions q0 where q0.active and q0.level=least(10,r.score/5+1) and not exists(select 1 from world_english_turns t where t.run_id=r.id and t.question_id=q0.id)
 order by exists(select 1 from (select tag from world_english_turns where run_id=r.id order by seq desc limit 2)x where x.tag=q0.tag),
 exists(select 1 from (select context_id from world_english_turns where run_id=r.id order by seq desc limit 5)x where x.context_id=q0.context_id),
 exists(select 1 from (select t.question_id from world_english_turns t join world_english_runs rr on rr.id=t.run_id where rr.user_id=r.user_id order by t.issued_at desc limit 150)x where x.question_id=q0.id),random() limit 1;
 if not found then update world_english_runs set status='completed',reason='bank_complete',ended_at=clock_timestamp() where id=r.id;return;end if;
 select array_agg(i order by random()) into order_ids from generate_series(0,2)i;
 select jsonb_agg(q.choices->x.i order by x.n),max((x.n-1)::int) filter(where x.i=q.correct_index) into shuffled,answer_pos from unnest(order_ids) with ordinality x(i,n);
 insert into world_english_turns(run_id,seq,question_id,tag,context_id,prompt,choices,correct_index,explanation)values(r.id,r.score+1,q.id,q.tag,q.context_id,q.prompt,shuffled,answer_pos,q.explanation);
 update world_english_runs set status='question' where id=r.id;
end;$$;
create or replace function public.world_english_public(p_run uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r world_english_runs;t world_english_turns;question jsonb;
begin
 select * into r from world_english_runs where id=p_run;if not found then return null;end if;
 select * into t from world_english_turns where run_id=r.id order by seq desc limit 1;
 if r.status='question' and t.answered_at is null and clock_timestamp()>=t.expires_at then
 update world_english_turns set answered_at=clock_timestamp(),chosen=-1,correct=false where id=t.id returning * into t;
 update world_english_runs set status='lost',reason='timeout',ended_at=clock_timestamp() where id=r.id returning * into r;
 end if;
 if t.id is not null then
 question:=jsonb_build_object('id',t.id,'number',t.seq,'prompt',t.prompt,'choices',t.choices,'expiresAt',t.expires_at);
 if t.answered_at is not null then question:=question||jsonb_build_object('correctIndex',t.correct_index,'chosen',t.chosen,'correct',t.correct,'explanation',t.explanation,'points',t.points);end if;
 end if;
 return jsonb_build_object('id',r.id,'score',r.score,'status',r.status,'reason',r.reason,'question',question);
end;$$;
create or replace function public.get_world_english_state() returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();rid uuid;run jsonb;d date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;
begin
 if u is null then raise exception 'authentication required';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select id into rid from world_english_runs where user_id=u order by created_at desc limit 1;run:=world_english_public(rid);
 return jsonb_build_object('serverNow',clock_timestamp(),'run',run,'best',coalesce((select score from world_english_best where user_id=u),0),'todayBest',coalesce((select best_score from world_english_daily where user_id=u and day=d),0),'todayPoints',coalesce((select points from world_english_daily where user_id=u and day=d),0),'dailyCap',300,'rankings',coalesce((select jsonb_agg(to_jsonb(x))from(select b.user_id,coalesce(nullif(p.display_name,''),'사용자') as name,b.score,b.reached_at from world_english_best b left join world_profiles p on p.user_id=b.user_id where b.score>0 order by b.score desc,b.reached_at,b.user_id limit 20)x),'[]'::jsonb));
end;$$;
create or replace function public.start_world_english(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();r world_english_runs;
begin
 if u is null then raise exception 'authentication required';end if;if p_request_id is null then raise exception 'request required';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into r from world_english_runs where user_id=u and request_id=p_request_id;if found then return get_world_english_state();end if;
 select * into r from world_english_runs where user_id=u and status in('question','review');if found then perform world_english_public(r.id);if (select status from world_english_runs where id=r.id)in('question','review')then return get_world_english_state();end if;end if;
 if(select count(*)from world_english_questions where active)<3000 then raise exception 'English bank is incomplete: run all of 030 SQL';end if;
 insert into world_english_runs(user_id,request_id)values(u,p_request_id)returning * into r;perform world_english_issue(r.id);return get_world_english_state();
end;$$;
create or replace function public.answer_world_english(p_run_id uuid,p_turn_id uuid,p_choice int,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();r world_english_runs;t world_english_turns;packet world_english_requests;payload jsonb;result jsonb;d date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;daily world_english_daily;award int:=0;newscore int;
begin
 if u is null then raise exception 'authentication required';end if;
 if p_request_id is null or p_choice is null or p_choice not between -1 and 2 then raise exception 'invalid answer';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,0));payload:=jsonb_build_array('answer',p_run_id,p_turn_id,p_choice);
 select * into packet from world_english_requests where user_id=u and request_id=p_request_id;if found then if packet.payload<>payload then raise exception 'request payload mismatch';end if;return packet.result;end if;
 select * into r from world_english_runs where id=p_run_id and user_id=u for update;if not found then raise exception 'run not found';end if;
 select * into t from world_english_turns where id=p_turn_id and run_id=r.id for update;if not found then raise exception 'question not found';end if;
 if t.answered_at is not null or r.status<>'question' or t.seq<>r.score+1 then return get_world_english_state();end if;
 if p_choice=-1 and clock_timestamp()<t.expires_at then raise exception 'question has not expired';end if;
 if clock_timestamp()>=t.expires_at then perform world_english_public(r.id);
 elsif p_choice=t.correct_index then
 newscore:=r.score+1;
 insert into world_english_best(user_id,score)values(u,newscore)on conflict(user_id)do update set score=excluded.score,reached_at=clock_timestamp() where world_english_best.score<excluded.score;
 insert into world_english_daily(user_id,day)values(u,d)on conflict do nothing;
 select * into daily from world_english_daily where user_id=u and day=d for update;
 award:=greatest(0,least(300,newscore*10)-daily.points);
 update world_english_daily set best_score=greatest(best_score,newscore),points=points+award where user_id=u and day=d;
 if award>0 then insert into world_points_ledger(user_id,amount,reason,reference_key)values(u,award,'영어 게임 일일 최고 기록','english:'||d::text||':'||newscore::text);end if;
 update world_english_turns set answered_at=clock_timestamp(),chosen=p_choice,correct=true,points=award where id=t.id;
 update world_english_runs set score=newscore,status='review' where id=r.id;
 else
 update world_english_turns set answered_at=clock_timestamp(),chosen=p_choice,correct=false where id=t.id;
 update world_english_runs set status='lost',reason='wrong',ended_at=clock_timestamp() where id=r.id;
 end if;
 result:=get_world_english_state();insert into world_english_requests values(u,p_request_id,payload,result);return result;
end;$$;
create or replace function public.next_world_english(p_run_id uuid,p_turn_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();r world_english_runs;t world_english_turns;
begin
 if u is null then raise exception 'authentication required';end if;perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 select * into r from world_english_runs where id=p_run_id and user_id=u for update;if not found then raise exception 'run not found';end if;
 select * into t from world_english_turns where run_id=r.id order by seq desc limit 1;
 if r.status='review' and t.id=p_turn_id then perform world_english_issue(r.id);end if;return get_world_english_state();
end;$$;
create or replace function public.quit_world_english(p_run_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();
begin
 if u is null then raise exception 'authentication required';end if;perform pg_advisory_xact_lock(hashtextextended(u::text,0));
 if not exists(select 1 from world_english_runs where id=p_run_id and user_id=u)then raise exception 'run not found';end if;
 perform world_english_public(p_run_id);update world_english_runs set status='quit',reason='quit',ended_at=clock_timestamp() where id=p_run_id and user_id=u and status in('question','review');return get_world_english_state();
end;$$;
do $$ declare t text;begin
 foreach t in array array['world_english_questions','world_english_runs','world_english_turns','world_english_best','world_english_daily','world_english_requests']loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);
 end loop;
